CREATE TABLE reservations (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), customer_id UNIQUEIDENTIFIER NOT NULL, facility_id UNIQUEIDENTIFIER NOT NULL, unit_type_id UNIQUEIDENTIFIER NOT NULL, preferred_start_date DATE NOT NULL, rental_months INT NOT NULL, assigned_unit_id UNIQUEIDENTIFIER NULL, estimated_price DECIMAL(19,2) NOT NULL, status NVARCHAR(30) NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE rental_contracts (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), reservation_id UNIQUEIDENTIFIER NOT NULL, customer_id UNIQUEIDENTIFIER NOT NULL, storage_unit_id UNIQUEIDENTIFIER NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, monthly_price DECIMAL(19,2) NOT NULL, deposit_amount DECIMAL(19,2) NOT NULL, status NVARCHAR(30) NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE handover_records (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), contract_id UNIQUEIDENTIFIER NOT NULL, type NVARCHAR(20) NOT NULL, scheduled_at DATETIME2 NULL, completed_at DATETIME2 NULL, staff_id UNIQUEIDENTIFIER NULL, unit_condition NVARCHAR(100) NULL, lock_handled BIT NOT NULL DEFAULT 0, access_card_handled BIT NOT NULL DEFAULT 0, access_code_handled BIT NOT NULL DEFAULT 0, notes NVARCHAR(1000) NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
